 * 7 days past its due date; REMINDER_1 from 7 days; REMINDER_2 from 21 days once the first reminder went out at
 * least 14 days before; FINAL from 45 days once the second went out; COLLECTIONS from 60 days once the final
 * notice went out.
 */
public DunningLevel dunningLevel(InvoiceStatus status, LocalDate today) {
    if (status != InvoiceStatus.OVERDUE || dueDate == null) {
        return DunningLevel.NONE;
    }
    long overdue = ChronoUnit.DAYS.between(dueDate, today);
    int sent = reminders.size();
    if (overdue < 7) {
        return DunningLevel.NONE;
    }
    if (overdue < 21 || sent < 1 || ChronoUnit.DAYS.between(reminders.get(0), today) < 14) {
        return DunningLevel.REMINDER_1;
    }
    if (overdue < 45 || sent < 2) {
        return DunningLevel.REMINDER_2;
    }
    if (overdue < 60 || sent < 3) {
        return DunningLevel.FINAL;
    }
    return DunningLevel.COLLECTIONS;
}

/** A reminder fee charged on the invoice: the fee, in its currency, charged the day the reminder went out. */
public record ReminderFee(LocalDate on, DunningLevel level, BigDecimal amount) {
}

/**
 * The fee for a reminder of the level sent on the day: the workspace's fee for the level in US dollars,
 * converted at the day's rate and rounded down to the step; nothing when the level has none.
 */
public BigDecimal reminderFee(DunningLevel level, LocalDate on) {
    if (reminderFeesUsd == null || reminderFeesUsd.isBlank()) {
        return zero();
    }
    for (String entry : reminderFeesUsd.split(",")) {
        String[] parts = entry.split("=");
        if (parts[0].trim().equals(level.name())) {
            return currency().divideDownToStep(new BigDecimal(parts[1].trim()), usdPerOn(on));
        }
    }
    return zero();
}

/**
 * The reminder fees charged on the invoice, earliest first: each reminder that went out (the n-th at the n-th
 * level after NONE) carries its level's fee from its day (see {@link #reminderFee}); those with no fee, and those
 * after the invoice was written off, charge nothing. A credit note is charged none.
 */
public List<ReminderFee> reminderFees() {
    List<ReminderFee> fees = new ArrayList<>();
    if (isCreditNote()) {
        return fees;
    }
    DunningLevel[] levels = DunningLevel.values();
    for (int n = 0; n < reminders.size() && n + 1 < levels.length; n++) {
        LocalDate on = reminders.get(n);
        if (writtenOffOn != null && on.isAfter(writtenOffOn)) {
            continue;
        }
        BigDecimal fee = reminderFee(levels[n + 1], on);
        if (fee.signum() > 0) {
            fees.add(new ReminderFee(on, levels[n + 1], fee));
        }
    }
    return fees;
}

/** The reminder fees charged on the invoice added up (see {@link #reminderFees}); 0 when none are. */
public BigDecimal getReminderFees() {
    return reminderFees().stream().map(ReminderFee::amount).reduce(zero(), BigDecimal::add);
}

/** Records that the reminder for the next dunning level went out on the given day; it has already been checked. */
public void remind(LocalDate on) {
    reminders.add(on);
}

/** Records a promise made on the given day to pay the amount by the date; it has already been checked. */
    if (withholdingThresholdUsd == null) {
        return zero();
    }
    return currency().divideDownToStep(new BigDecimal(withholdingThresholdUsd.trim()), usdPerOn(issueDate));
}

/** Whether an invoice needs approval before it is sent, has been approved, or needs none. */
public enum Approval {
    NOT_NEEDED, NEEDS_APPROVAL, APPROVED
}

/**
 * The grand total above which a draft needs approval: the approval limit (the client tier's, else the workspace's) in US dollars
 * converted at the issue date's rate, rounded down to the step; null when none is set. A MEDIUM payment risk
 * client's limit is halved in US dollars before it is converted.
 */
private BigDecimal approvalLimit() {
    if (approvalLimitUsd == null) {
        return null;
    }
    BigDecimal usd = new BigDecimal(approvalLimitUsd.trim());
    if (approvalLimitHalved) {
        usd = usd.divide(BigDecimal.valueOf(2));
    }
    return currency().divideDownToStep(usd, usdPerOn(issueDate));
}

/** Halves the approval limit (or restores it): a MEDIUM payment risk client has half the limit. */
public void halveApprovalLimit(boolean halved) {
    this.approvalLimitHalved = halved;
}

/** Marks the client as a HIGH payment risk (or not): every draft of such a client needs two approvals. */
public void markHighRisk(boolean highRisk) {
    this.highRiskClient = highRisk;
}

/** Drops the grace period (or gives it back): a HIGH payment risk client's invoices are overdue the day after they fall due. */
